import{_ as e,o as d,c as l,ao as a}from"./chunks/framework.CGAfXaNK.js";const y=JSON.parse('{"title":"Code layout","description":"","frontmatter":{},"headers":[],"relativePath":"developers/index.md","filePath":"developers/index.md","lastUpdated":null}'),o={name:"developers/index.md"};function s(r,t,i,n,c,h){return d(),l("div",null,[...t[0]||(t[0]=[a('<h1 id="Code-layout" tabindex="-1">Code layout <a class="header-anchor" href="#Code-layout" aria-label="Permalink to &quot;Code layout {#Code-layout}&quot;">​</a></h1><p>This section is for people who want to change or extend MTGeophysics.jl. It collects the details that the user pages leave out: every control file key, how the 2D solver treats topography, the equations of the 2D inversions, and how to add a new inversion algorithm.</p><p>For how to contribute (branches, tests, pull requests) see <a href="https://github.com/JuliaGeophysics/MTGeophysics.jl/blob/main/CONTRIBUTING.md" target="_blank" rel="noreferrer">CONTRIBUTING.md</a>.</p><h2 id="1D" tabindex="-1">1D <a class="header-anchor" href="#1D" aria-label="Permalink to &quot;1D {#1D}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">File</th><th style="text-align:left;">Contents</th></tr></thead><tbody><tr><td style="text-align:left;"><code>src/Fwd1D.jl</code></td><td style="text-align:left;">layer recursion, <code>mt1d_layers</code>, <code>MakeMesh1D</code>, Fréchet derivatives, <code>ForwardSolve1D</code></td></tr><tr><td style="text-align:left;"><code>src/Inv1D.jl</code></td><td style="text-align:left;"><code>InvCtrl1D</code>, <code>Invert1D</code> (its own GN and VFSA), 1D plots</td></tr></tbody></table><p>1D is self-contained: it shares only the data and model file formats and the plot style with 2D, so changes to the 2D solver or inversions cannot change 1D results.</p><h2 id="2D" tabindex="-1">2D <a class="header-anchor" href="#2D" aria-label="Permalink to &quot;2D {#2D}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">File</th><th style="text-align:left;">Contents</th></tr></thead><tbody><tr><td style="text-align:left;"><code>src/Control2D.jl</code></td><td style="text-align:left;"><code>fwd.ctrl</code>, <code>inv.ctrl</code>, VFSA control, <code>cov.ctrl</code> and <code>mask.ctrl</code> readers and writers</td></tr><tr><td style="text-align:left;"><code>src/Mesh2D.jl</code></td><td style="text-align:left;">mesh geometry, topography helpers, model builders and model I/O</td></tr><tr><td style="text-align:left;"><code>src/Fwd2D.jl</code></td><td style="text-align:left;">TE/TM solver, data I/O, misfit, Fréchet derivatives (G, G δm, Gᵗ δd̂)</td></tr><tr><td style="text-align:left;"><code>src/Strike2D.jl</code></td><td style="text-align:left;">phase tensor strike estimate and rotation to the strike frame</td></tr><tr><td style="text-align:left;"><code>src/Topo2D.jl</code></td><td style="text-align:left;"><code>topo.dat</code>, topography and water cut into models</td></tr><tr><td style="text-align:left;"><code>src/Mask2D.jl</code></td><td style="text-align:left;">masks for <code>cov.ctrl</code> and <code>mask.ctrl</code></td></tr><tr><td style="text-align:left;"><code>src/MakeMesh2D.jl</code>, <code>src/MakeMesh2DGUI.jl</code></td><td style="text-align:left;">the 2D mesh tool, batch and GLMakie</td></tr><tr><td style="text-align:left;"><code>src/Inv2D.jl</code></td><td style="text-align:left;">problem setup, objective, regularisation, line search, driver, six-file <code>Invert2D</code></td></tr><tr><td style="text-align:left;"><code>src/Inv2D_GN.jl</code></td><td style="text-align:left;">damped Gauss–Newton</td></tr><tr><td style="text-align:left;"><code>src/Inv2D_NLCG.jl</code></td><td style="text-align:left;">preconditioned nonlinear conjugate gradients</td></tr><tr><td style="text-align:left;"><code>src/Inv2D_VFSA.jl</code></td><td style="text-align:left;">very fast simulated annealing, its ensemble and the five-file <code>VFSA2D</code></td></tr><tr><td style="text-align:left;"><code>src/PlotModel2D.jl</code></td><td style="text-align:left;">resistivity sections and the mesh</td></tr><tr><td style="text-align:left;"><code>src/PlotData2D.jl</code></td><td style="text-align:left;">data curves and fit, convergence, <code>PlotInversion2D</code></td></tr></tbody></table><p>The continuous problem the 2D solver discretises is stated at the top of <code>src/Fwd2D.jl</code>.</p><h2 id="3D-and-shared" tabindex="-1">3D and shared <a class="header-anchor" href="#3D-and-shared" aria-label="Permalink to &quot;3D and shared {#3D-and-shared}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">File</th><th style="text-align:left;">Contents</th></tr></thead><tbody><tr><td style="text-align:left;"><code>src/Data.jl</code>, <code>src/Model.jl</code></td><td style="text-align:left;">ModEM data and model I/O</td></tr><tr><td style="text-align:left;"><code>src/WS3DModel.jl</code></td><td style="text-align:left;">WS3D model I/O</td></tr><tr><td style="text-align:left;"><code>src/Rotate.jl</code></td><td style="text-align:left;"><code>rotate_data</code> and the rotation history</td></tr><tr><td style="text-align:left;"><code>src/Chi2RMS.jl</code>, <code>src/Distortion.jl</code></td><td style="text-align:left;">3D misfit, with and without galvanic distortion</td></tr><tr><td style="text-align:left;"><code>src/MakeMesh3D.jl</code>, <code>src/MakeMesh3DGUI.jl</code></td><td style="text-align:left;">the 3D mesh tool</td></tr><tr><td style="text-align:left;"><code>src/MeshToMesh.jl</code></td><td style="text-align:left;">resampling a model onto another mesh</td></tr><tr><td style="text-align:left;"><code>src/Mask3D.jl</code></td><td style="text-align:left;">topography and bathymetry of 3D models</td></tr><tr><td style="text-align:left;"><code>src/VFSA3DMT.jl</code></td><td style="text-align:left;">3D VFSA with ModEM as the forward solver, and ensemble statistics</td></tr><tr><td style="text-align:left;"><code>src/CoreUtils3D.jl</code></td><td style="text-align:left;">core and padding detection</td></tr><tr><td style="text-align:left;"><code>src/PhaseTensor.jl</code></td><td style="text-align:left;">phase tensors, induction vectors and their GIS export</td></tr><tr><td style="text-align:left;"><code>src/PlotModel3D.jl</code>, <code>src/PlotData3D.jl</code>, <code>src/EditModel3D.jl</code></td><td style="text-align:left;">GLMakie viewers and editors</td></tr></tbody></table><h2 id="Tests" tabindex="-1">Tests <a class="header-anchor" href="#Tests" aria-label="Permalink to &quot;Tests {#Tests}&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=.</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test/runtests.jl</span></span></code></pre></div><p><code>test/TestFrechet2D.jl</code> checks the 2D Fréchet derivatives against finite differences and with the dot-product test; <code>test/TestTopography2D.jl</code> checks the solver against a published topography model (see <a href="./solver2d">2D solver notes</a>).</p>',14)])])}const g=e(o,[["render",s]]);export{y as __pageData,g as default};
